1	import { dockLabel } from "@pirate-sea-race/content";
2	import { defaultSimulationConfig, dockInReach, NOT_DOCKED, toTilePosition } from "@pirate-sea-race/simulation";
3	import { cssColor, slotColor, type ShipSnapshot } from "./matchView.js";
4	
5	export type ConnectionStatus = "connected" | "disconnected";
6	
7	export interface HudModel {
8	  readonly code: string;
9	  readonly protocolVersion: number;
10	  readonly custom: boolean;
11	  readonly status: ConnectionStatus;
12	  readonly selfId: string;
13	  /** Players in the match, including those out of sight. */
14	  readonly players: number;
15	  /** The ships the server sent: the player's own and those in sight. */
16	  readonly ships: readonly ShipSnapshot[];
17	}
18	
19	function field(root: ParentNode, id: string): HTMLElement {
20	  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
21	  if (element === null) throw new Error(`missing HUD field ${id}`);
22	  return element;
23	}
24	
25	/** "Palm Key, south dock" when moored, "at sea" otherwise. */
26	export function dockText(dock: number): string {
27	  return dock === NOT_DOCKED ? "at sea" : dockLabel(defaultSimulationConfig.map, dock);
28	}
29	
30	/**
31	 * What the player can do about docking right now, by the simulation's own rule (`dockInReach`; speed does not matter):
32	 * nothing to say when moored or far from any dock; otherwise press E.
33	 */
34	export function dockHint(ship: Pick<ShipSnapshot, "x" | "y" | "dock">): string {
35	  if (ship.dock !== NOT_DOCKED) return "";
36	  const config = defaultSimulationConfig;
37	  const berth = dockInReach(config, ship.x, ship.y);
38	  return berth === undefined ? "" : `Press E to dock at ${dockLabel(config.map, berth.id)}`;
39	}
40	
41	/** Writes the match status and the latest authoritative (not interpolated) state of the visible ships. */
42	export function renderHud(root: ParentNode, model: HudModel): void {
43	  field(root, "hud-code").textContent = model.code;
44	  field(root, "hud-protocol").textContent = `v${model.protocolVersion}`;
45	  field(root, "hud-players").textContent = String(model.players);
46	  field(root, "hud-status").textContent = model.status;
47	  field(root, "hud-mode").textContent = model.custom ? "custom" : "standard";
48	  field(root, "hud-self").textContent = model.selfId;
49	  const own = model.ships.find((ship) => ship.id === model.selfId);
50	  const dock = field(root, "hud-dock");
51	  dock.textContent = own === undefined ? "" : dockText(own.dock);
52	  dock.dataset["dock"] = String(own?.dock ?? NOT_DOCKED);
53	  field(root, "hud-dock-hint").textContent = own === undefined ? "" : dockHint(own);
54	
55	  const list = field(root, "positions");
56	  const items = model.ships.map((ship) => {
57	    const item = document.createElement("li");
58	    item.dataset["shipId"] = ship.id;
59	    item.dataset["slot"] = String(ship.slot);
60	    item.dataset["x"] = String(ship.x);
61	    item.dataset["y"] = String(ship.y);
62	    item.dataset["heading"] = String(ship.heading);
63	    item.dataset["speed"] = String(ship.speed);
64	    item.dataset["dock"] = String(ship.dock);
65	    const swatch = document.createElement("span");
66	    swatch.className = "swatch";
67	    swatch.style.background = cssColor(slotColor(ship.slot));
68	    const tile = toTilePosition(defaultSimulationConfig, ship.x, ship.y);
69	    const who = ship.id === model.selfId ? "you" : ship.id;
70	    item.append(swatch, `${who}: tile ${tile.tileX},${tile.tileY}, heading ${ship.heading}, speed ${ship.speed}`);
71	    return item;
72	  });
73	  list.replaceChildren(...items);
74	}
75

