1	/**
2	 * Converts the Tiled sea map (`assets/source/maps/slice-sea.tmj`, the subset documented in
3	 * `packages/content/src/tiledMap.ts`) into the typed module `packages/content/src/maps/sliceSea.ts`, after checking
4	 * it against the map validators. `--check` writes nothing and fails when the module is out of date.
5	 *
6	 *   npm run map:build      convert and write
7	 *   npm run map:check      compare only
8	 */
9	import { readFileSync, writeFileSync } from "node:fs";
10	import { fileURLToPath } from "node:url";
11	import { shipTuning } from "../packages/content/src/sailing.js";
